}

.dgs-talk-backdrop {
  position: absolute !important;
  inset: 0 !important;
  background:
    radial-gradient(circle at 22% 18%, rgba(253,92,98,.20), transparent 34%),
    radial-gradient(circle at 80% 78%, rgba(253,92,98,.14), transparent 32%),
    rgba(8,8,8,.84) !important;
