}

@keyframes pulse {
  0%, 100% { transform: scale(1); opacity: 1; box-shadow: 0 0 0 0 rgba(233, 30, 140, 0.7); }
  50% { transform: scale(1.25); opacity: 0.82; box-shadow: 0 0 0 10px rgba(233, 30, 140, 0); }
}

@keyframes float {
  0%, 100% { transform: translate(0, 0) scale(1) rotate(0deg); }
  33% { transform: translate(35px, -35px) scale(1.12) rotate(5deg); }
  66% { transform: translate(-25px, 25px) scale(0.92) rotate(-5deg); }
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(34px); }
  to { opacity: 1; transform: translateY(0); }
}

.dgs-gradient-text {
  background: linear-gradient(270deg, var(--brand-magenta), var(--brand-purple), var(--brand-orange), var(--brand-magenta));
  background-size: 400% 400%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  display: inline-block;
  animation: gradientPulse 4s ease infinite;
}

/* ─── HERO ─────────────────────────────────────────── */
.dgs-geo-hero {
  position: relative;
  min-height: 78vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding: 96px 20px 72px;
}

.dgs-hero-container {
  max-width: 1060px;
  margin: 0 auto;
  text-align: center;
  position: relative;
  z-index: 2;
}

.dgs-elite-badge {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  box-shadow: 0 8px 32px rgba(233, 30, 140, 0.15);
  border-radius: 50px;
  padding: 11px 24px;
  font-size: 14px;
  font-weight: 500;
  margin-bottom: 30px;
  animation: fadeInUp 0.6s ease-out;
  letter-spacing: 0.4px;
}

.dgs-pulse-dot {
  width: 10px;
  height: 10px;
  background: var(--gradient-brand);
  border-radius: 50%;
  animation: pulse 2s ease-in-out infinite;
}

.dgs-hero-title {
  font-size: clamp(40px, 6.4vw, 66px);
  font-weight: 700;
  line-height: 1.12;
  margin-bottom: 22px;
  animation: fadeInUp 0.8s ease-out 0.2s backwards;
}

.dgs-hero-description {
  font-size: clamp(17px, 2.1vw, 20px);
  color: var(--text-soft);
  max-width: 880px;
  margin: 0 auto 34px;
  line-height: 1.75;
  animation: fadeInUp 1s ease-out 0.4s backwards;
}

.dgs-hero-cta {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 16px;
  animation: fadeInUp 1.2s ease-out 0.6s backwards;
}

.dgs-btn-primary,
.dgs-btn-secondary,
.dgs-btn-whatsapp {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 16px 30px;
  border-radius: 10px;
  font-weight: 600;
  font-size: 16px;
  text-decoration: none;
  transition: all 0.3s ease;
  border: 1px solid transparent;
  position: relative;
  overflow: hidden;
}

.dgs-btn-primary {
  background: linear-gradient(270deg, var(--brand-magenta), var(--brand-purple), var(--brand-orange), var(--brand-magenta));
  background-size: 400% 400%;
  color: #ffffff;
  animation: gradientPulse 4s ease infinite;
  box-shadow: 0 8px 32px rgba(233, 30, 140, 0.3);
}

.dgs-btn-primary:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 40px rgba(233, 30, 140, 0.4);
}

.dgs-btn-secondary,
.dgs-btn-whatsapp {
  background: rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  color: #ffffff;
  border-color: rgba(255, 255, 255, 0.2);
}

.dgs-btn-secondary:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: var(--brand-magenta);
  box-shadow: 0 8px 32px rgba(233, 30, 140, 0.2);
}

.dgs-btn-whatsapp:hover {
  background: rgba(37, 211, 102, 0.15);
  border-color: #25D366;
  box-shadow: 0 8px 32px rgba(37, 211, 102, 0.2);
}

.dgs-hero-bg-element {
  position: absolute;
  border-radius: 50%;
  filter: blur(140px);
  opacity: 0.14;
  pointer-events: none;
}

.dgs-hero-bg-1 {
  width: 560px;
  height: 560px;
  background: radial-gradient(circle, var(--brand-magenta) 0%, transparent 70%);
  top: -160px;
  left: -160px;
  animation: float 25s ease-in-out infinite, gradientPulse 8s ease infinite;
}

.dgs-hero-bg-2 {
  width: 470px;
  height: 470px;
  background: radial-gradient(circle, var(--brand-purple) 0%, transparent 70%);
  top: 38%;
  right: -150px;
  animation: float 30s ease-in-out infinite 5s, gradientPulse 10s ease infinite;
}

.dgs-hero-bg-3 {
  width: 620px;
  height: 620px;
  background: radial-gradient(circle, var(--brand-orange) 0%, transparent 70%);
  bottom: -260px;
  left: 35%;
  animation: float 35s ease-in-out infinite 10s, gradientPulse 12s ease infinite;
}

/* ─── CLIENTS ──────────────────────────────────────── */
.dgs-clients {
  padding: 48px 20px;
  background: rgba(255, 255, 255, 0.01);
  backdrop-filter: blur(10px);
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.dgs-clients-title {
  text-align: center;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 2.4px;
  color: rgba(255, 255, 255, 0.45);
  margin-bottom: 30px;
  font-weight: 500;
}

.dgs-clients-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(145px, 1fr));
  gap: 28px;
  align-items: center;
  max-width: 1050px;
  margin: 0 auto;
}

.dgs-client-logo {
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0.7;
  transition: opacity 0.3s ease, transform 0.3s ease;
}

.dgs-client-logo:hover {
  opacity: 1;
  transform: scale(1.05);
}

.dgs-client-logo img {
  max-width: 128px;
  height: auto;
}

/* ─── SECTION SYSTEM ───────────────────────────────── */
.dgs-section {
  padding: 72px 20px;
}

.dgs-section.alt-bg {
  background: rgba(255, 255, 255, 0.012);
}

.dgs-section-header {
  text-align: center;
  max-width: 900px;
  margin: 0 auto 42px;
}

.dgs-section-tag {
  display: inline-block;
  padding: 8px 18px;
  background: rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 50px;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 18px;
  color: rgba(255, 255, 255, 0.7);
  font-weight: 500;
}

.dgs-section-title {
  font-size: clamp(34px, 5.4vw, 52px);
  font-weight: 700;
  margin-bottom: 18px;
  line-height: 1.14;
}

.dgs-section-subtitle {
  font-size: 18px;
  color: rgba(255, 255, 255, 0.70);
  line-height: 1.75;
}

/* ─── COMPACT CONTENT GRID ─────────────────────────── */
.dgs-compact-grid {
  display: grid;
  grid-template-columns: 1.05fr .95fr;
  gap: 22px;
  align-items: stretch;
}

.dgs-compact-card {
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: 16px;
  padding: 30px;
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  position: relative;
  overflow: hidden;
}

.dgs-compact-card::before,
.dgs-feature-card::before,
.dgs-impact-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--gradient-brand);
  opacity: 0.78;
}

.dgs-compact-card h2,
.dgs-compact-card h3 {
  font-size: clamp(24px, 3vw, 34px);
  line-height: 1.22;
  margin: 0 0 16px;
  font-weight: 700;
}

.dgs-compact-card p {
  font-size: 16px;
  color: var(--text-soft);
  line-height: 1.76;
  margin-bottom: 14px;
}

.dgs-compact-card p:last-child {
  margin-bottom: 0;
}

.dgs-compact-card strong {
  color: #ffffff;
}

.dgs-quick-list {
  display: grid;
  gap: 10px;
  list-style: none;
  margin: 18px 0 0;
  padding: 0;
}

.dgs-quick-list li {
  position: relative;
  padding: 13px 15px 13px 38px;
  background: rgba(255,255,255,0.025);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 10px;
  color: var(--text-soft);
  font-size: 15px;
  line-height: 1.55;
}

.dgs-quick-list li::before {
  content: "";
  position: absolute;
  left: 16px;
  top: 23px;
  width: 13px;
  height: 2px;
  background: var(--gradient-brand);
}

/* ─── FEATURE CARDS ───────────────────────────────── */
.dgs-feature-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
}

.dgs-feature-card {
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: 16px;
  padding: 26px 24px;
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
  height: 100%;
}

.dgs-feature-card:hover,
.dgs-impact-card:hover {
  transform: translateY(-5px);
  border-color: rgba(233, 30, 140, 0.35);
  box-shadow: 0 16px 46px rgba(0, 0, 0, 0.32);
}

.dgs-card-kicker {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 1.3px;
  text-transform: uppercase;
  color: var(--brand-magenta);
  margin-bottom: 12px;
}

.dgs-feature-card h3 {
  font-size: 20px;
  line-height: 1.28;
  margin-bottom: 12px;
  font-weight: 700;
}

.dgs-feature-card p {
  font-size: 15px;
  line-height: 1.72;
  color: rgba(255,255,255,0.68);
}

/* ─── STEP CARDS ──────────────────────────────────── */
.dgs-framework-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  align-items: stretch;
  margin-top: 28px;
}

.dgs-framework-card {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  min-height: 96px;
  padding: 22px 24px;
  background: #070707;
  border: 1px solid rgba(255,255,255,0.10);
  border-radius: 16px;
}

.dgs-framework-number {
  width: 28px;
  height: 28px;
  min-width: 28px;
  min-height: 28px;
  border-radius: 50%;
  border: 1px solid var(--brand-magenta);
  color: var(--brand-magenta);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 700;
  line-height: 1;
  margin-top: 2px;
}

.dgs-framework-title {
  margin: 0;
  color: #ffffff;
  font-size: 18px;
  line-height: 1.45;
  font-weight: 500;
  text-align: left;
}

/* ─── IMPACT CARDS ────────────────────────────────── */
.dgs-impact-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
}

.dgs-impact-card {
  background: var(--card-bg);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid var(--card-border);
  border-radius: 14px;
  padding: 26px 24px;
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
  height: 100%;
}

.dgs-impact-title {
  font-size: 17px;
  font-weight: 700;
  margin-bottom: 10px;
  color: #ffffff;
  line-height: 1.35;
}

.dgs-impact-desc {
  font-size: 14.5px;
  color: rgba(255, 255, 255, 0.66);
  line-height: 1.68;
}


/* ─── CASE STUDIES ─────────────────────────────────── */
.dgs-case-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 22px;
  align-items: stretch;
}

.dgs-case-card {
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: 18px;
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 100%;
  transition: all 0.3s ease;
}

.dgs-case-card:hover {
  transform: translateY(-6px);
  border-color: rgba(233, 30, 140, 0.35);
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.34);
}

.dgs-case-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--gradient-brand);
  z-index: 2;
}

.dgs-case-image {
  height: 190px;
  overflow: hidden;
  background: #080808;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}

.dgs-case-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: top;
  display: block;
}

.dgs-case-body {
  padding: 24px;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.dgs-case-logo {
  height: 32px;
  margin-bottom: 14px;
}

.dgs-case-logo img {
  height: 100%;
  width: auto;
  max-width: 160px;
  object-fit: contain;
  display: block;
}

.dgs-case-tag {
  display: inline-flex;
  align-self: flex-start;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.1px;
  text-transform: uppercase;
  padding: 6px 11px;
  border-radius: 999px;
  background: rgba(233, 30, 140, 0.10);
  border: 1px solid rgba(233, 30, 140, 0.22);
  color: var(--brand-magenta);
  margin-bottom: 14px;
}

.dgs-case-title {
  color: #ffffff;
  font-size: 21px;
  line-height: 1.32;
  font-weight: 700;
  margin: 0 0 12px;
}

.dgs-case-desc {
  color: rgba(255,255,255,0.68);
  font-size: 15px;
  line-height: 1.7;
  margin-bottom: 20px;
}

.dgs-case-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-top: auto;
}

.dgs-case-metric {
  text-align: center;
  padding: 13px 8px;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 10px;
}

.dgs-case-metric strong {
  display: block;
  font-size: 22px;
  line-height: 1;
  font-weight: 800;
  margin-bottom: 6px;
  background: linear-gradient(270deg, var(--brand-magenta), var(--brand-purple), var(--brand-orange), var(--brand-magenta));
  background-size: 400% 400%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: gradientPulse 4s ease infinite;
}

.dgs-case-metric span {
  display: block;
  font-size: 10px;
  line-height: 1.35;
  color: rgba(255,255,255,0.52);
  text-transform: uppercase;
  letter-spacing: 0.7px;
}

.dgs-case-disclaimer {
  max-width: 860px;
  margin: 26px auto 0;
  text-align: center;
  font-size: 13.5px;
  line-height: 1.65;
  color: rgba(255,255,255,0.52);
}

/* ─── CTA ─────────────────────────────────────────── */
.dgs-cta-section {
  padding: 72px 20px;
  background: linear-gradient(135deg, rgba(233,30,140,0.055) 0%, rgba(185,30,140,0.05) 50%, rgba(255,107,53,0.055) 100%);
  text-align: center;
  position: relative;
  overflow: hidden;
}

.dgs-cta-content {
  max-width: 880px;
  margin: 0 auto;
  position: relative;
  z-index: 2;
  padding: 46px 38px;
  background: rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(30px);
  -webkit-backdrop-filter: blur(30px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 22px;
  box-shadow: 0 8px 32px rgba(233, 30, 140, 0.15);
}

.dgs-cta-title {
  font-size: clamp(32px, 5vw, 48px);
  font-weight: 700;
  margin-bottom: 18px;
  line-height: 1.18;
}

.dgs-cta-description {
  font-size: 17px;
  color: rgba(255, 255, 255, 0.76);
  margin-bottom: 30px;
  line-height: 1.75;
}

.dgs-cta-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  justify-content: center;
}

/* ─── FAQ ─────────────────────────────────────────── */
.dgs-faq-section {
  padding: 72px 20px;
}

.dgs-faq-container {
  max-width: 940px;
  margin: 0 auto;
}

.dgs-faq-item {
  background: rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 12px;
  margin-bottom: 16px;
  overflow: hidden;
  transition: all 0.3s ease;
}

.dgs-faq-item:hover {
  border-color: rgba(233, 30, 140, 0.3);
  box-shadow: 0 8px 32px rgba(233, 30, 140, 0.1);
}

.dgs-faq-question {
  padding: 24px 26px;
  font-size: 18px;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
}

.dgs-faq-answer {
  padding: 0 26px 24px;
  color: rgba(255, 255, 255, 0.75);
  line-height: 1.78;
  font-size: 16px;
  display: none;
}

.dgs-faq-item.active .dgs-faq-answer {
  display: block;
}

.dgs-faq-toggle {
  font-size: 24px;
  transition: transform 0.3s ease;
  background: var(--gradient-brand);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  flex-shrink: 0;
}

.dgs-faq-item.active .dgs-faq-toggle {
  transform: rotate(45deg);
}

/* ─── FORM ────────────────────────────────────────── */
.dgs-final-cta {
  padding: 72px 20px;
  background: rgba(255, 255, 255, 0.012);
}

.dgs-final-cta-container {
  max-width: 900px;
  margin: 0 auto;
  text-align: center;
}

.dgs-final-cta-container h2 {
  font-size: clamp(32px, 5vw, 48px);
  font-weight: 700;
  margin-bottom: 18px;
  line-height: 1.18;
}

.dgs-final-cta-container > p {
  font-size: 17px;
  color: rgba(255, 255, 255, 0.75);
  margin-bottom: 34px;
  line-height: 1.75;
}

.dgs-form-shortcode {
  background: rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(30px);
  -webkit-backdrop-filter: blur(30px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 16px;
  padding: 34px;
  margin-bottom: 34px;
  box-shadow: 0 8px 32px rgba(233, 30, 140, 0.1);
}

.dgs-contact-info {
  display: flex;
  justify-content: center;
  gap: 22px;
  flex-wrap: wrap;
}

.dgs-contact-item {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 15px 24px;
  background: rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 10px;
  color: rgba(255, 255, 255, 0.85);
  text-decoration: none;
  font-size: 15px;
  transition: all 0.3s ease;
}

.dgs-contact-item:hover {
  border-color: var(--brand-magenta);
  background: rgba(255, 255, 255, 0.08);
  box-shadow: 0 8px 32px rgba(233, 30, 140, 0.2);
  transform: translateY(-2px);
}

.dgs-contact-item svg {
  width: 19px;
  height: 19px;
}

/* ─── FLUENT FORM CLEANUP + DARK THEME ─────────────── */
.dgs-form-shortcode .fluentform,
.dgs-form-shortcode form {
  text-align: left;
}

.dgs-form-shortcode .ff-el-group {
  margin-bottom: 18px;
}

.dgs-form-shortcode label,
.dgs-form-shortcode .ff-el-input--label label {
  color: rgba(255,255,255,0.82) !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  margin-bottom: 8px !important;
}

.dgs-form-shortcode input,
.dgs-form-shortcode textarea,
.dgs-form-shortcode select,
.dgs-form-shortcode .ff-el-form-control {
  width: 100% !important;
  background: rgba(255,255,255,0.06) !important;
  border: 1px solid rgba(255,255,255,0.16) !important;
  color: #ffffff !important;
  border-radius: 10px !important;
  min-height: 48px !important;
  padding: 13px 15px !important;
  box-shadow: none !important;
  outline: none !important;
}

.dgs-form-shortcode textarea,
.dgs-form-shortcode textarea.ff-el-form-control {
  min-height: 120px !important;
}

.dgs-form-shortcode input::placeholder,
.dgs-form-shortcode textarea::placeholder {
  color: rgba(255,255,255,0.42) !important;
}

.dgs-form-shortcode input:focus,
.dgs-form-shortcode textarea:focus,
.dgs-form-shortcode select:focus,
.dgs-form-shortcode .ff-el-form-control:focus {
  border-color: var(--brand-magenta) !important;
